// Brand factory: creates a nominal type distinct from its primitive
declare const Brand: unique symbol;
type Branded<T, TBrand> = T & { readonly [Brand]: TBrand };

// Specific branded types for each domain concept
type UserId = Branded<string, 'UserId'>;
type TenantId = Branded<string, 'TenantId'>;
type DocumentId = Branded<string, 'DocumentId'>;
type SessionId = Branded<string, 'SessionId'>;

// Constructor functions that apply the brand (runtime: just a string)
const UserId = (raw: string): UserId => raw as UserId;
const TenantId = (raw: string): TenantId => raw as TenantId;

// Function requiring specific branded types
function getDocumentsForTenant(tenantId: TenantId, userId: UserId) {
  return fetch(`/api/tenants/${tenantId}/documents?userId=${userId}`);
}

// Usage: TypeScript enforces correct argument order
const tenant = TenantId('t-corp-001');
const user = UserId('u-alice-999');

getDocumentsForTenant(tenant, user); // ✅ Correct
// getDocumentsForTenant(user, tenant); // ❌ Compile error: UserId not assignable to TenantId

// Each state has exactly the data it needs—no extra null fields
type ChatState =
  | { status: 'idle' }
  | { status: 'submitting'; prompt: string }
  | { status: 'streaming'; prompt: string; accumulatedContent: string; controller: AbortController }
  | { status: 'awaiting_approval'; prompt: string; action: PendingAction; actionId: string }
  | { status: 'completed'; prompt: string; finalContent: string; citations: Citation[] }
  | { status: 'error'; prompt: string; error: Error };

interface PendingAction { toolName: string; description: string; parameters: Record<string, unknown>; }
interface Citation { chunkId: string; documentTitle: string; }

// TypeScript narrows the type inside each branch
function renderChatState(state: ChatState): JSX.Element {
  switch (state.status) {
    case 'idle':
      return <PromptInput />;  // only idle data available
    case 'streaming':
      return <StreamingView content={state.accumulatedContent} />;  // accumulatedContent guaranteed
    case 'awaiting_approval':
      return <ApprovalModal action={state.action} actionId={state.actionId} />;
    case 'completed':
      return <CompletedMessage content={state.finalContent} citations={state.citations} />;
    case 'error':
      return <ErrorDisplay error={state.error} />;
    case 'submitting':
      return <LoadingSpinner />;  
    default:
      return exhaustiveCheck(state); // TypeScript verifies all cases are handled
  }
}

// Exhaustiveness sentinel: if this runs, the switch is incomplete
declare function exhaustiveCheck(state: never): never;

type TokenEvent = { type: 'token'; content: string };
type DoneEvent = { type: 'done' };
type ErrorEvent = { type: 'error'; code: string; message: string };
type SseEvent = TokenEvent | DoneEvent | ErrorEvent;

// Type guard: returns `value is TokenEvent`, not just `boolean`
function isTokenEvent(value: unknown): value is TokenEvent {
  return (
    typeof value === 'object' &&
    value !== null &&
    'type' in value &&
    (value as any).type === 'token' &&
    typeof (value as any).content === 'string'
  );
}

function isErrorEvent(value: unknown): value is ErrorEvent {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as any).type === 'error' &&
    typeof (value as any).message === 'string'
  );
}

// Safe parsing of raw SSE data
function parseSsePayload(rawData: string): SseEvent | null {
  try {
    const parsed: unknown = JSON.parse(rawData);
    if (isTokenEvent(parsed)) return parsed;   // type narrowed to TokenEvent
    if (isErrorEvent(parsed)) return parsed;   // type narrowed to ErrorEvent
    if (typeof parsed === 'object' && parsed !== null && (parsed as any).type === 'done') {
      return { type: 'done' };
    }
    return null;
  } catch {
    return null;
  }
}
